// Java Kafka producer tuned for high throughput and idempotence
import org.apache.kafka.clients.producer.*;
import java.util.Properties;

Properties props = new Properties();
props.put("bootstrap.servers", "broker1:9092,broker2:9092");
props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
// Throughput / durability tuning
props.put("compression.type", "lz4");
props.put("linger.ms", "20");      // batch for up to 20ms
props.put("batch.size", "65536"); // 64KB batches
// Idempotent producer to avoid duplicates on retries
props.put("enable.idempotence", "true");

Producer<String, String> producer = new KafkaProducer<>(props);
ProducerRecord<String, String> rec = new ProducerRecord<>("activity_events", userId, payload);
producer.send(rec, (metadata, exception) -> {
  if (exception != null) exception.printStackTrace();
  else System.out.println("sent to " + metadata.topic() + "@" + metadata.partition());
});
producer.flush();
producer.close();

