/* JavaScript: exponential backoff + full jitter */
async function retry(fn, { retries = 5, baseDelay = 100, maxDelay = 10000, isRetryable = () => true } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt++;
      if (attempt > retries || !isRetryable(err)) throw err;
      const exp = Math.min(maxDelay, baseDelay * Math.pow(2, attempt));
      const wait = Math.floor(Math.random() * exp); // full jitter
      await new Promise(res => setTimeout(res, wait));
    }
  }
}
